from PIL import Image
import numpy as np
a=np.array(Image.open('first_frame.png')).astype(int)
# fit boundaries via mask card brightness >145, excluding bg x<80 or >180
for y in [54,55,56,60,70,80,90,100,110,120,123]:
 row=a[y].mean(1)
 for t in [145,150,155,160]:
  m=row>t
  xs=np.where(m)[0]
  # find runs length >10
  runs=[]
  if len(xs):
   st=xs[0];pr=xs[0]
   for x in xs[1:]:
    if x>pr+1:
     if pr-st>5:runs.append((st,pr))
     st=x
    pr=x
   if pr-st>5:runs.append((st,pr))
  print(y,t,runs)
 print()
