from PIL import Image
import numpy as np
a=np.array(Image.open('first_frame.png')).astype(int)
# boundary find via color jump >50 at each row around card, run values
for y in range(54,126):
 # find left jump around 78-90 and right around 165-180
 L=[];R=[]
 for x in range(76,90):
  if abs(a[y,x].mean()-a[y,x+1].mean())>20:L.append(x)
 for x in range(166,181):
  if abs(a[y,x].mean()-a[y,x+1].mean())>20:R.append(x)
 if y%3==0:print(y,L,R)
